WITH youngest_client AS (
    SELECT client_id FROM client WHERE birth_date = (SELECT MIN(birth_date) FROM client)
), highest_salary_client AS (
    SELECT client_id FROM district GROUP BY client_id ORDER BY A11 DESC LIMIT 1
)
SELECT client_id FROM youngest_client INTERSECT SELECT client_id FROM highest_salary_client

